"use strict";(self.webpackChunk=self.webpackChunk||[]).push([["8560"],{28026:function(e,n,t){t.r(n),t.d(n,{frontMatter:()=>o,default:()=>u,toc:()=>h,metadata:()=>a,assets:()=>l,contentTitle:()=>d});var a=JSON.parse('{"id":"tour/design","title":"Design decisions","description":"The following are design decisions that guide the development of D2. We\'ve tried our best","source":"@site/docs/tour/design.md","sourceDirName":"tour","slug":"/tour/design","permalink":"/d2-docs-cn-llm/tour/design","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{},"sidebar":"tourSidebar","previous":{"title":"Dev tool vs design tool","permalink":"/d2-docs-cn-llm/tour/experience"},"next":{"title":"Getting help & community","permalink":"/d2-docs-cn-llm/tour/community"}}'),i=t(85893),s=t(50065),r=t(45180);let o={},d="Design decisions",l={},h=[{value:"Readability &gt; prototyping speed",id:"readability--prototyping-speed",level:2},{value:"Warnings &gt; errors",id:"warnings--errors",level:2},{value:"Good defaults",id:"good-defaults",level:2},{value:"Optimized for desktops and servers",id:"optimized-for-desktops-and-servers",level:2},{value:"Singular use case: documenting software",id:"singular-use-case-documenting-software",level:2},{value:"Design the system, not the diagram",id:"design-the-system-not-the-diagram",level:2},{value:"Whiteboard-fit",id:"whiteboard-fit",level:2}];function c(e){let n={code:"code",h1:"h1",h2:"h2",header:"header",p:"p",pre:"pre",...(0,s.a)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"design-decisions",children:"Design decisions"})}),"\n","\n",(0,i.jsx)(n.p,{children:"The following are design decisions that guide the development of D2. We've tried our best\nto avoid the mistakes of the past and take inspiration from the most successful modern\nprogramming and configuration languages."}),"\n",(0,i.jsx)(n.p,{children:"Design decisions inherently mean tradeoffs, some of which you may disagree with. But, if\nyou're a programmer, D2 is built for you, and we believe you'll find the sum of these\ndecisions to be a language that makes you feels at home."}),"\n",(0,i.jsx)(n.p,{children:"These will inevitably evolve as the language continues to evolve."}),"\n",(0,i.jsx)(n.h2,{id:"readability--prototyping-speed",children:"Readability > prototyping speed"}),"\n",(0,i.jsx)(n.p,{children:"Both readability and prototyping speed are important, but when a decision is one or the\nother, D2 usually favors readability."}),"\n",(0,i.jsx)(n.p,{children:"Most of the time, it's not either/or. Good programming language features usually result in\nhigher vectors in both directions. D2's syntax is light and designed such that autofmt\nalways gets it right for you, consistent across projects."}),"\n",(0,i.jsx)(n.p,{children:"Hopefully you'll find a good balance between ease of use, prototyping speed, and\nreadability, in that order. What D2 specifically avoids is terse, compact syntax that\ninhibits all three."}),"\n",(0,i.jsx)(n.p,{children:"For example, here's two ways to define a cylinder."}),"\n",(0,i.jsx)(n.p,{children:"D2:"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-d2",children:"A: Christmas {shape: cylinder}\n"})}),"\n",(0,i.jsx)(n.p,{children:"Mermaid:"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"A[(Christmas)]\n"})}),"\n",(0,i.jsxs)(n.p,{children:["D2's is a little less compact but a lot more readable. It's also more writeable, by which\nI mean you don't forget that a cylinder is called a cylinder, but it's easy to forget that\n",(0,i.jsx)(n.code,{children:"[(x)]"})," is a cylinder."]}),"\n",(0,i.jsx)(n.h2,{id:"warnings--errors",children:"Warnings > errors"}),"\n",(0,i.jsx)(n.p,{children:"D2 will compile whenever possible. For example, say you apply a class that doesn't exist,\nor add a style that has no effect on a particular shape. If the user error is one that D2\ncan ignore, it will compile successfully and, at most, warn. There's nothing more annoying\nthan commenting out some code while debugging, and getting a stop-the-world error message\nthat you have an unused variable."}),"\n",(0,i.jsx)(n.h2,{id:"good-defaults",children:"Good defaults"}),"\n",(0,i.jsx)(n.p,{children:"Default, zero-customization D2 should produce good diagrams. That requires being\nopinionated on what a good default should be. For example, D2 ships with a default theme.\nInstead of keeping things open-ended with monochrome shapes, pleasant colors are the\ndefault."}),"\n",(0,i.jsx)(n.h2,{id:"optimized-for-desktops-and-servers",children:"Optimized for desktops and servers"}),"\n",(0,i.jsxs)(n.p,{children:["D2 has a robust CLI with a built-in watch mode, maintained ",(0,i.jsx)(n.code,{children:"man"})," page, and allows reading\nfrom stdin and writing to stdout. Images and fonts are by default embedded into the\ndiagram so that exported diagrams are standalone -- they'll look the same everywhere. D2\nsupports a wide variety of formats like PPT and GIF. It allows imports, such that you can\nmodularize your diagram into multiple files. There's a language API to programmatically\nedit and write D2. All of these are antithetical to a web library for browser rendering.\nD2 intends to ship and maintain a web library for that purpose, but it'll be trimmed down\nfrom the full feature set and secondary in priority."]}),"\n",(0,i.jsx)(n.h2,{id:"singular-use-case-documenting-software",children:"Singular use case: documenting software"}),"\n",(0,i.jsx)(n.p,{children:"D2 is focused on being useful to software engineers for documenting software. We are not a\ngeneral-purpose visualization tool. Other languages may support mind maps, Gantt charts,\nSankey, venn diagrams, and have the capability to draw a map of the United States. D2 does\nnone of those and will not support these."}),"\n",(0,i.jsx)(n.p,{children:"In D2, these are considered bloat. Stretching a language thin across such a large surface\narea of different diagram types essentially splits it into N different mini-DSLs within a\nDSL. Syntax can hardly evolve when it has to support N completely different diagram types.\nAnd it's counter to the original purpose of a DSL which is to make a subset task more\nconvenient."}),"\n",(0,i.jsx)(n.h2,{id:"design-the-system-not-the-diagram",children:"Design the system, not the diagram"}),"\n",(0,i.jsx)(n.p,{children:"The purpose of D2 is to describe the system you're documenting. The language should make a\nclear separation between design of the system and design of the diagram."}),"\n",(0,i.jsx)(n.p,{children:"Consider what it takes to customize styles in a Graphviz diagram:"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:'digraph "Linux_kernel_diagram" {\n	fontname="Helvetica,Arial,sans-serif"\n	node [fontname="Helvetica,Arial,sans-serif"]\n	edge [fontname="Helvetica,Arial,sans-serif"]\n	graph [\n		newrank = true,\n		nodesep = 0.3,\n		ranksep = 0.2,\n		overlap = true,\n		splines = false,\n	]\n	node [\n		fixedsize = false,\n		fontsize = 24,\n		height = 1,\n		shape = box,\n		style = "filled,setlinewidth(5)",\n		width = 2.2\n	]\n	edge [\n		arrowhead = none,\n		arrowsize = 0.5,\n		labelfontname = "Ubuntu",\n		weight = 10,\n		style = "filled,setlinewidth(5)"\n	]\n'})}),"\n",(0,i.jsx)(n.p,{children:"Imagine if you couldn't separate HTML and CSS and it all had to be inlined."}),"\n",(0,i.jsx)(n.p,{children:"Of course, good aesthetics are essential to good documentation. D2 certainly prioritizes\naesthetics, but it must be decoupled with the content."}),"\n",(0,i.jsx)(n.p,{children:"D2 is the only language that allows you to define just nodes and edges, and import all the\nstyles in a separate file, and swap out that file for different aesthetics."}),"\n",(0,i.jsx)(n.h2,{id:"whiteboard-fit",children:"Whiteboard-fit"}),"\n",(0,i.jsx)(n.p,{children:'While "graph" and "diagram" are often interchangeable terms, for D2\'s purposes, a diagram\nis a simplified representation that can fit on a large whiteboard. After a certain number\nof nodes and edges, e.g. 1000 nodes, the representation becomes more like a graph from\ngraph theory than a software architecture diagram. Their use case is less understanding\neach individual shape and connection and more seeing the general patterns. D2 is not\ndesigned for this use case. There are much better tools for that.'}),"\n",(0,i.jsx)(r.Z,{src:t(73879).Z,webpSrc:t(12299).Z,width:300,alt:"graph example"})]})}function u(e={}){let{wrapper:n}={...(0,s.a)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},73879:function(e,n,t){t.d(n,{Z:()=>a});let a=t.p+"assets/images/graph-e9eff330c0fd3f11ee569855d7ef3fbf.png"},12299:function(e,n,t){t.d(n,{Z:()=>a});let a=t.p+"assets/images/graph-ce35493f6c6e02689c6a5a7f56e06cc2.webp"},45180:function(e,n,t){t.d(n,{Z:()=>i});var a=t(85893);t(67294);let i=({src:e,webpSrc:n,alt:t,className:i,style:s,width:r,height:o,...d})=>{if(!n)throw Error(`WebPImage component requires explicit webpSrc prop. Found src: ${e}`);let l={display:"block",...r&&!s?.width?{width:r}:{},...o&&!s?.height?{height:o}:{},...s||{}};return(0,a.jsxs)("picture",{style:l,className:i,children:[(0,a.jsx)("source",{srcSet:n,type:"image/webp"}),(0,a.jsx)("img",{src:e,alt:t,loading:"lazy",...d})]})}},50065:function(e,n,t){t.d(n,{Z:()=>o,a:()=>r});var a=t(67294);let i={},s=a.createContext(i);function r(e){let n=a.useContext(s);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),a.createElement(s.Provider,{value:n},e.children)}}}]);